create table public.student_progress (id uuid primary key default gen_random_uuid(), student_id uuid not null unique references public.profiles(id) on delete cascade, current_level integer not null default 1 check (current_level > 0), total_xp integer not null default 0 check (total_xp >= 0), activities_completed integer not null default 0 check (activities_completed >= 0), challenges_completed integer not null default 0 check (challenges_completed >= 0), exams_completed integer not null default 0 check (exams_completed >= 0), projects_completed integer not null default 0 check (projects_completed >= 0), last_activity_at timestamptz, created_at timestamptz not null default now(), updated_at timestamptz not null default now());;
